{
  "book_code": "4BAR",
  "verses": [
    {
      "chapter": 3,
      "text_ar": "احرصوا على آنية خدمة الهيكل حتى اجتماع الحبيب.",
      "verse": 11
    },
    {
      "chapter": 3,
      "text_ar": "وتحدث إرميا قائلًا: \"أتوسل إليك يا رب، أرني ماذا أفعله لأبيمالك الحبشي، لأنه صنع إحسانات كثيرة لعبدك إرميا.",
      "verse": 12
    },
    {
      "chapter": 3,
      "text_ar": "لأنه انتشلني من الجب الطيني، وأنا لا أريد أن يرى خراب هذه المدينة ودمارها، بل أريد أن ترحمه وتجنبه الحزن\".",
      "verse": 13
    },
    {
      "chapter": 3,
      "text_ar": "وقال الرب لإرميا: \"أرسله إلى كرم أغريباس، وسأخبئه في ظل الجبل حتى أرد الشعب إلى المدينة.",
      "verse": 14
    },
    {
      "chapter": 3,
      "text_ar": "وأما أنت يا إرميا، فاذهب مع شعبك إلى بابل وأقم معهم، واكرز لهم، حتى أرددهم إلى المدينة\".",
      "verse": 15
    }
  ]
}
